# ==============================================================
# PyTorch Dataset for prokaryotic sequence + label windows.
# In-memory; uses full (L, 6) sequence and (L,) per-strand labels (6-state).
# ==============================================================

import numpy as np
import torch
from torch.utils.data import Dataset


# Reverse-complement one-hot: reverse sequence and swap A-T, C-G channels (0-3); keep N (4) and softmask (5).
REVCOMP_CHANNELS = [3, 2, 1, 0, 4, 5]


class ProkaDataset(Dataset):
    """
    Sliding-window dataset over one chromosome: 6-channel one-hot sequence and 6-state labels,
    forward and reverse strand per window.
    """

    def __init__(
        self,
        sequence_matrix: np.ndarray,
        labels_fwd: np.ndarray,
        labels_rev: np.ndarray,
        window_size: int = 10000,
        step: int = 5000,
    ):
        """
        Args:
            sequence_matrix: (L, 6) one-hot from FASTA (e.g. GenomeSequences.get_full_encoded_sequence).
            labels_fwd: (L,) int labels for forward strand (e.g. Annotation.get_full_chromosome_labels [0]).
            labels_rev: (L,) int labels for reverse strand (same [1]).
            window_size: Window length in bp.
            step: Step between window starts.
        """
        assert sequence_matrix.ndim == 2 and sequence_matrix.shape[1] == 6
        assert labels_fwd.shape == labels_rev.shape == (sequence_matrix.shape[0],)
        self.seq = np.asarray(sequence_matrix, dtype=np.float32)
        self.labels_fwd = np.asarray(labels_fwd, dtype=np.int64)
        self.labels_rev = np.asarray(labels_rev, dtype=np.int64)
        self.window_size = int(window_size)
        self.step = int(step)
        self.seq_len = self.seq.shape[0]
        self.starts = np.arange(
            0, max(0, self.seq_len - self.window_size + 1), self.step, dtype=np.int64
        )

    def __len__(self) -> int:
        return len(self.starts)

    def __getitem__(self, idx: int):
        start = int(self.starts[idx])
        end = start + self.window_size

        # Forward: direct slice
        x_fwd = self.seq[start:end]
        y_fwd = self.labels_fwd[start:end]

        # Reverse: reverse sequence and complement channels; reverse labels so 5' aligns with sequence
        x_rev = self.seq[start:end][::-1, :][:, REVCOMP_CHANNELS].copy()
        y_rev = self.labels_rev[start:end][::-1].copy()

        return (
            torch.from_numpy(x_fwd),
            torch.from_numpy(y_fwd),
            torch.from_numpy(x_rev),
            torch.from_numpy(y_rev),
        )


def make_proka_dataset(
    genome,
    annotation,
    seq_name: str,
    window_size: int = 10000,
    step: int = 5000,
) -> ProkaDataset:
    """
    Build a ProkaDataset for one chromosome from GenomeSequences and Annotation.
    Uses get_full_encoded_sequence(seq_name) and get_full_chromosome_labels(seq_name, seq_len).
    """
    seq_matrix = genome.get_full_encoded_sequence(seq_name)
    seq_len = seq_matrix.shape[0]
    labels_fwd, labels_rev = annotation.get_full_chromosome_labels(seq_name, seq_len)
    return ProkaDataset(
        sequence_matrix=seq_matrix,
        labels_fwd=labels_fwd,
        labels_rev=labels_rev,
        window_size=window_size,
        step=step,
    )
